#!/usr/bin/env bash
# ============================================================================
# VideoMind rebuild, Part 1a: wallet sign in, sessions and ownership
# ============================================================================
# FOR THE rebuild BRANCH ONLY. It refuses to run on main.
#
# Until now the API trusted whatever wallet address the caller sent. After
# this part the caller must prove the wallet is theirs:
#
#   1. the API issues a one time nonce
#   2. the wallet signs a message with it (signMessage, no gas, no funds)
#   3. the API checks the signature, the key, the nonce and that the wallet
#      itself stamped this site's address on the message
#   4. the API opens a 7 day session and returns a token
#
# Every library, upload, delete, search and assistant route then acts as
# the signed in wallet and ignores any wallet value the caller sends.
# Public video pages and chat on a shared video still need no sign in.
#
#   BACKEND   3 new files, 9 changed. One database migration (users,
#             sessions, auth_nonces, videos.owner_wallet), applied once
#             when the service starts.
#   FRONTEND  4 new files, 10 changed. A sign in prompt, the session in
#             the browser, the token on every request.
#
# No package changes. No lockfile changes.
#
#   ./vm_signin.sh            apply
#   ./vm_signin.sh --force    apply even if local files differ from GitHub
#   ./vm_signin.sh --revert   restore everything from the latest backup
#
# Run from the repo root (dir containing backend/ and frontend/).
# ============================================================================
set -euo pipefail

MARKER="vm_signin"
STAMP="$(date +%Y%m%d-%H%M%S)"
BAKDIR=".vm_signin_backups"

ADD=(
  "backend/src/lib/migrations.ts"
  "backend/src/lib/auth.ts"
  "backend/src/routes/auth.ts"
  "frontend/src/lib/session.ts"
  "frontend/src/lib/signin.ts"
  "frontend/src/components/layout/AuthProvider.tsx"
  "frontend/src/components/layout/SignInNotice.tsx"
)
