  "backend/src/routes/chat.ts"
  "backend/src/routes/learn.ts"
  "backend/src/routes/stats.ts"
  "frontend/src/lib/api.ts"
  "frontend/src/components/layout/AppProviders.tsx"
  "frontend/src/components/layout/Navbar.tsx"
  "frontend/src/components/layout/WalletButton.tsx"
  "frontend/src/components/layout/ShelbyBadge.tsx"
  "frontend/src/app/library/page.tsx"
  "frontend/src/app/learn/page.tsx"
  "frontend/src/app/assistant/page.tsx"
  "frontend/src/components/search/SearchInterface.tsx"
  "frontend/src/components/upload/UploadZone.tsx"
)
