grep -q "$MARKER" "$TMPD/a1"                 || die "auth.ts payload missing marker. Aborting."
grep -q 'parseFullMessage' "$TMPD/a1"        || die "auth.ts payload lost the message check. Aborting."
grep -q 'requireAuth' "$TMPD/m5"             || die "videos.ts payload lost the sign in guard. Aborting."
grep -q 'limitDelete' "$TMPD/m5"             || die "videos.ts payload lost the delete limit. Aborting."
grep -q 'locationHint: SHELBY_LOCATION' "$TMPD/m18" || die "UploadZone payload lost locationHint. Aborting."
grep -q 'account.address as any' "$TMPD/m18" || die "UploadZone payload lost the signer shape. Aborting."
say "26 payloads decoded and verified."

# ---- backups ----
mkdir -p "$BAKDIR/$STAMP"
for f in "${MOD[@]}"; do cp "$f" "$BAKDIR/$STAMP/$(bname "$f")"; done
for f in "${ADD[@]}"; do if [ -f "$f" ]; then cp "$f" "$BAKDIR/$STAMP/$(bname "$f")"; fi; done
say "Backups saved to $BAKDIR/$STAMP/"

rollback() {
  restore_from "$BAKDIR/$STAMP"
  die "$1 All files restored from $BAKDIR/$STAMP."
}

# ---- write ----
i=0; for f in "${ADD[@]}"; do mkdir -p "$(dirname "$f")"; cp "$TMPD/a$i" "$f" || rollback "Could not write $f."; i=$((i+1)); done
i=0; for f in "${MOD[@]}"; do cp "$TMPD/m$i" "$f" || rollback "Could not write $f."; i=$((i+1)); done

i=0; for f in "${ADD[@]}"; do [ "$(sha "$f")" = "${NEW_ADD[$i]}" ] || rollback "$f write verify failed."; i=$((i+1)); done
i=0; for f in "${MOD[@]}"; do [ "$(sha "$f")" = "${NEW_MOD[$i]}" ] || rollback "$f write verify failed."; i=$((i+1)); done

say "Applied wallet sign in (rebuild Part 1a)."
say "Verify BOTH packages before pushing:"
say "  cd backend  && npx tsc --noEmit"
say "  cd frontend && npx tsc --noEmit && npm run build"
say "Undo: ./vm_signin.sh --revert"
